options.onAppendButtonClick:
var txt = this.getWidgetRef('txtNode',false).getValue();   

if(txt == "")
{
  this.$message.warning("请输入桶号！")
  return;
}

this.getFormRef().executeDataSource('searchapi', {'containerNo': txt}).then(res => {
    if(res == null)
    {
      var tree = this.getWidgetRef("preTree",false);
      tree.loadDataFromDS();
      this.$message.warning("找不到该桶号的绑桶信息！")
      return;
    }

    var ntree = this.getWidgetRef("preTree",false).getNativeTree();
    ntree.filter(res.prescriptionNo);
});

